-- Review candidate: ordinary profile operations, never privileged identity provisioning.
CREATE ROLE nexustalent_profile_writer NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB;
GRANT USAGE ON SCHEMA nexustalent TO nexustalent_profile_writer;
GRANT SELECT, INSERT, UPDATE ON nexustalent.records TO nexustalent_profile_writer;
GRANT EXECUTE ON FUNCTION nexustalent.actor_role() TO nexustalent_profile_writer;
CREATE POLICY profile_read ON nexustalent.records FOR SELECT TO nexustalent_profile_writer USING (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','PUBLISH_INSTITUTION_AVAILABILITY','UPDATE_STUDENT_AVAILABILITY','ADD_VERIFIED_SKILL','REGISTER_INDEPENDENT_CANDIDATE','PROVISION_USER_ROLE') AND document_path NOT LIKE '%/%/%' AND ((collection='users' AND document_path='users/'||current_setting('nexustalent.actor_uid',true)) OR ((collection='students' AND document_path='students/'||current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','UPDATE_STUDENT_AVAILABILITY','REGISTER_INDEPENDENT_CANDIDATE')) OR (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.profile_action',true) IN ('ADD_VERIFIED_SKILL','PROVISION_USER_ROLE')) AND current_setting('nexustalent.profile_action',true)='ADD_VERIFIED_SKILL'))) OR (collection='institutions' AND document_path='institutions/'||current_setting('nexustalent.target_id',true) AND ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true)='PUBLISH_INSTITUTION_AVAILABILITY')) OR (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.profile_action',true) IN ('ADD_VERIFIED_SKILL','PROVISION_USER_ROLE')) AND current_setting('nexustalent.profile_action',true)='PROVISION_USER_ROLE' AND collection IN ('users','students','institutions','employers') AND document_path=collection||'/'||current_setting('nexustalent.target_id',true)))
 OR ((((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','UPDATE_STUDENT_AVAILABILITY','REGISTER_INDEPENDENT_CANDIDATE')) OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true)='PUBLISH_INSTITUTION_AVAILABILITY') OR ((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.profile_action',true) IN ('ADD_VERIFIED_SKILL','PROVISION_USER_ROLE'))) AND collection='auditEvents' AND document_path='auditEvents/'||encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.profile_action',true),'UTF8')),'hex') AND payload->>'actorUid'=current_setting('nexustalent.actor_uid',true) AND payload->>'action'=current_setting('nexustalent.profile_action',true))));
CREATE POLICY profile_insert ON nexustalent.records FOR INSERT TO nexustalent_profile_writer WITH CHECK (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','PUBLISH_INSTITUTION_AVAILABILITY','UPDATE_STUDENT_AVAILABILITY','ADD_VERIFIED_SKILL','REGISTER_INDEPENDENT_CANDIDATE','PROVISION_USER_ROLE') AND document_path NOT LIKE '%/%/%' AND ((((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','UPDATE_STUDENT_AVAILABILITY','REGISTER_INDEPENDENT_CANDIDATE')) AND current_setting('nexustalent.profile_action',true)='REGISTER_INDEPENDENT_CANDIDATE' AND collection='students' AND document_path='students/'||current_setting('nexustalent.actor_uid',true) AND payload->>'id'=current_setting('nexustalent.actor_uid',true)
 AND payload->>'candidateType'='independent_direct' AND payload->>'institutionId'='inst-independent' AND payload->>'institutionVerificationStatus'='not_applicable' AND payload->>'platformVerificationStatus'='pending'
 AND payload->'isEmpanelledCampus'='false'::jsonb AND payload->'skills'='[]'::jsonb AND payload->'projects'='[]'::jsonb AND payload->'internships'='[]'::jsonb AND payload->'assessments'='[]'::jsonb AND payload->'evidenceIds'='[]'::jsonb AND payload->'campaignConsents'='{}'::jsonb
 AND payload->>'placementStatus'='unplaced' AND payload->>'availability'='actively_seeking' AND payload->'globalDataPrivacy'='{"allowUnsolicitedPings":false,"anonymizeProfileUntilConsent":true,"shareVerifiedBadgesGlobally":false,"autoDeclineBelowMinSalary":false}'::jsonb
 AND payload-ARRAY['id','name','email','avatar','candidateType','isEmpanelledCampus','institutionId','institutionName','institutionCode','rollNumber','institutionVerificationStatus','platformVerificationStatus','verificationNotes','independentCredentials','state','program','branch','graduationYear','cgpa','skills','projects','internships','assessments','evidenceIds','campaignConsents','preferences','availability','placementStatus','globalDataPrivacy']='{}'::jsonb)
 OR ((((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','UPDATE_STUDENT_AVAILABILITY','REGISTER_INDEPENDENT_CANDIDATE')) OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true)='PUBLISH_INSTITUTION_AVAILABILITY') OR ((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.profile_action',true) IN ('ADD_VERIFIED_SKILL','PROVISION_USER_ROLE'))) AND collection='auditEvents' AND document_path='auditEvents/'||encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.profile_action',true),'UTF8')),'hex') AND payload->>'eventId'=split_part(document_path,'/',2) AND payload->>'actorUid'=current_setting('nexustalent.actor_uid',true) AND payload->>'actorRole'=(SELECT nexustalent.actor_role()) AND payload->>'requestId'=current_setting('nexustalent.request_id',true) AND payload->>'action'=current_setting('nexustalent.profile_action',true) AND payload->'immutable'='true'::jsonb AND payload->'ids'=jsonb_build_array(current_setting('nexustalent.target_id',true)))));
CREATE POLICY profile_update ON nexustalent.records FOR UPDATE TO nexustalent_profile_writer USING (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','PUBLISH_INSTITUTION_AVAILABILITY','UPDATE_STUDENT_AVAILABILITY','ADD_VERIFIED_SKILL','REGISTER_INDEPENDENT_CANDIDATE','PROVISION_USER_ROLE') AND document_path NOT LIKE '%/%/%' AND ((collection='students' AND document_path='students/'||current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='student' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','UPDATE_STUDENT_AVAILABILITY','REGISTER_INDEPENDENT_CANDIDATE')) OR (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.profile_action',true) IN ('ADD_VERIFIED_SKILL','PROVISION_USER_ROLE')) AND current_setting('nexustalent.profile_action',true)='ADD_VERIFIED_SKILL'))) OR (collection='institutions' AND document_path='institutions/'||current_setting('nexustalent.target_id',true) AND ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) AND current_setting('nexustalent.profile_action',true)='PUBLISH_INSTITUTION_AVAILABILITY')) OR (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true' AND current_setting('nexustalent.profile_action',true) IN ('ADD_VERIFIED_SKILL','PROVISION_USER_ROLE')) AND current_setting('nexustalent.profile_action',true)='PROVISION_USER_ROLE' AND collection IN ('users','students','institutions','employers') AND document_path=collection||'/'||current_setting('nexustalent.target_id',true))) AND ((collection='students' AND current_setting('nexustalent.profile_action',true) IN ('UPDATE_GLOBAL_PRIVACY','UPDATE_STUDENT_AVAILABILITY','ADD_VERIFIED_SKILL')) OR (collection='institutions' AND current_setting('nexustalent.profile_action',true)='PUBLISH_INSTITUTION_AVAILABILITY') OR (collection='users' AND current_setting('nexustalent.profile_action',true)='PROVISION_USER_ROLE')));
CREATE FUNCTION nexustalent.guard_profile_write() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE a text:=current_setting('nexustalent.profile_action',true); k text; fields text[]; v jsonb; old_arr jsonb; new_arr jsonb; entry jsonb; expected jsonb; target_role text;
BEGIN
 IF NOT pg_has_role(current_user,'nexustalent_profile_writer','MEMBER') OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND rolsuper) THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF split_part(NEW.document_path,'/',1)='students' THEN
   IF NOT EXISTS(SELECT 1 FROM nexustalent.records WHERE document_path='users/'||current_setting('nexustalent.actor_uid',true) AND payload->>'uid'=current_setting('nexustalent.actor_uid',true) AND payload->>'email'=NEW.payload->>'email') THEN RAISE EXCEPTION 'Independent candidate identity mismatch' USING ERRCODE='23514'; END IF;
   IF jsonb_typeof(NEW.payload->'independentCredentials') IS DISTINCT FROM 'object' OR (NEW.payload->'independentCredentials')-ARRAY['collegeName','universityAffiliation','state','city','degree','branch','graduationYear','cgpa','rollNumber','submissionDate']<>'{}'::jsonb
    OR jsonb_typeof(NEW.payload->'graduationYear') IS DISTINCT FROM 'number' OR (NEW.payload->>'graduationYear')::numeric NOT BETWEEN 1950 AND 2100 OR trunc((NEW.payload->>'graduationYear')::numeric)<>(NEW.payload->>'graduationYear')::numeric
    OR jsonb_typeof(NEW.payload->'cgpa') IS DISTINCT FROM 'number' OR (NEW.payload->>'cgpa')::numeric NOT BETWEEN 0 AND 10
    OR NEW.payload->'independentCredentials'->'graduationYear' IS DISTINCT FROM NEW.payload->'graduationYear' OR NEW.payload->'independentCredentials'->'cgpa' IS DISTINCT FROM NEW.payload->'cgpa'
   THEN RAISE EXCEPTION 'Invalid independent credentials' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
 END IF;
 IF a='UPDATE_GLOBAL_PRIVACY' AND OLD.collection='students' THEN
  fields:=ARRAY['globalDataPrivacy']; v:=NEW.payload->'globalDataPrivacy';
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR v-ARRAY['allowUnsolicitedPings','anonymizeProfileUntilConsent','shareVerifiedBadgesGlobally','autoDeclineBelowMinSalary']<>'{}'::jsonb OR EXISTS(SELECT 1 FROM jsonb_each(v) x WHERE jsonb_typeof(x.value)<>'boolean') THEN RAISE EXCEPTION 'Invalid privacy settings' USING ERRCODE='23514'; END IF;
 ELSIF a='UPDATE_STUDENT_AVAILABILITY' AND OLD.collection='students' THEN
  fields:=ARRAY['availability']; IF COALESCE(NEW.payload->>'availability','') NOT IN ('actively_seeking','open_to_offers','not_currently_available') THEN RAISE EXCEPTION 'Invalid student availability' USING ERRCODE='23514'; END IF;
 ELSIF a='PUBLISH_INSTITUTION_AVAILABILITY' AND OLD.collection='institutions' THEN
  fields:=ARRAY['publishedAvailability']; old_arr:=COALESCE(OLD.payload->'publishedAvailability','[]'::jsonb); new_arr:=NEW.payload->'publishedAvailability'; entry:=new_arr->0;
  IF OLD.payload->>'empanelmentStatus' IS DISTINCT FROM 'empanelled' OR jsonb_typeof(new_arr) IS DISTINCT FROM 'array' OR jsonb_array_length(new_arr)>200 OR (new_arr-0) IS DISTINCT FROM old_arr OR entry-ARRAY['batchYear','branch','talentCount','description','publishedAt']<>'{}'::jsonb
   OR jsonb_typeof(entry->'batchYear') IS DISTINCT FROM 'number' OR (entry->>'batchYear')::numeric NOT BETWEEN 2000 AND 2100 OR trunc((entry->>'batchYear')::numeric)<>(entry->>'batchYear')::numeric
   OR jsonb_typeof(entry->'talentCount') IS DISTINCT FROM 'number' OR (entry->>'talentCount')::numeric NOT BETWEEN 0 AND 100000 OR trunc((entry->>'talentCount')::numeric)<>(entry->>'talentCount')::numeric
   OR length(trim(COALESCE(entry->>'branch',''))) NOT BETWEEN 1 AND 200 OR length(trim(COALESCE(entry->>'description',''))) NOT BETWEEN 1 AND 2000 OR COALESCE(entry->>'publishedAt','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  THEN RAISE EXCEPTION 'Invalid availability publication' USING ERRCODE='23514'; END IF;
 ELSIF a='ADD_VERIFIED_SKILL' AND OLD.collection='students' THEN
  fields:=ARRAY['skills']; new_arr:=NEW.payload->'skills'; entry:=new_arr->0;
  IF jsonb_typeof(new_arr) IS DISTINCT FROM 'array' OR jsonb_typeof(entry) IS DISTINCT FROM 'object' OR length(trim(COALESCE(entry->>'name',''))) NOT BETWEEN 1 AND 200 OR entry->>'verifiedBy' IS DISTINCT FROM current_setting('nexustalent.actor_uid',true)
   OR COALESCE(entry->>'category','') NOT IN ('technical','domain','communication','tools') OR COALESCE(entry->>'badge','') NOT IN ('Gold','Silver','Bronze','Verified')
   OR jsonb_typeof(entry->'score') IS DISTINCT FROM 'number' OR (entry->>'score')::numeric NOT BETWEEN 0 AND 100 OR (entry->>'percentile')::numeric IS DISTINCT FROM least(99,round((entry->>'score')::numeric*1.05))
   OR entry-ARRAY['name','category','score','percentile','badge','verifiedAt','verifiedBy']<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid verified skill' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(x.value ORDER BY x.ord),'[]'::jsonb) INTO expected FROM jsonb_array_elements(COALESCE(OLD.payload->'skills','[]'::jsonb)) WITH ORDINALITY x(value,ord) WHERE lower(x.value->>'name') IS DISTINCT FROM lower(entry->>'name');
  IF (new_arr-0) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Unrelated skill replacement' USING ERRCODE='23514'; END IF;
 ELSIF a='PROVISION_USER_ROLE' AND OLD.collection='users' THEN
  fields:=ARRAY['role','updatedAt']; target_role:=NEW.payload->>'role';
  IF OLD.payload->>'uid' IS DISTINCT FROM current_setting('nexustalent.target_id',true) OR current_setting('nexustalent.actor_uid',true)=current_setting('nexustalent.target_id',true) OR OLD.payload->>'role'='super_admin' OR COALESCE(target_role,'') NOT IN ('employer','institution','student','simulation') THEN RAISE EXCEPTION 'Privileged role changes prohibited' USING ERRCODE='23514'; END IF;
  IF target_role IS DISTINCT FROM OLD.payload->>'role' AND EXISTS(SELECT 1 FROM nexustalent.records WHERE collection IN ('employers','institutions','students') AND document_path=collection||'/'||current_setting('nexustalent.target_id',true) AND collection<>CASE target_role WHEN 'employer' THEN 'employers' WHEN 'institution' THEN 'institutions' WHEN 'student' THEN 'students' ELSE '' END) THEN RAISE EXCEPTION 'Stakeholder role requires reconciliation' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'Unrelated profile write' USING ERRCODE='23514'; END IF;
 IF (NEW.payload-fields) IS DISTINCT FROM (OLD.payload-fields) THEN RAISE EXCEPTION 'Unrelated profile modification' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END
$$;
CREATE TRIGGER profile_write_guard BEFORE INSERT OR UPDATE ON nexustalent.records FOR EACH ROW EXECUTE FUNCTION nexustalent.guard_profile_write();
REVOKE ALL ON FUNCTION nexustalent.guard_profile_write() FROM PUBLIC;
